import React, { useState } from 'react';
import Background from '../components/Background';
import MeshSphere from '../components/MeshSphere';
import { useMoods, useThoughts } from '../hooks/useStorage';

const MOOD_COLOR = { 1:'#c17070', 2:'#b88860', 3:'#9a9068', 4:'#6a9878', 5:'#6888b0' };
const MOOD_LABEL = { 1:'Väldigt dåligt', 2:'Dåligt', 3:'Okej', 4:'Bra', 5:'Väldigt bra' };
const TRAP_SHORT = {
  'Katastrofiering':'Katastr.', 'Tankeläsning':'Tankeläs.',
  'Svartvitt tänkande':'Svart/Vit', 'Övergeneralisering':'Övergener.',
  'Känslomässigt resonerande':'Känslo.', 'Personalisering':'Personal.',
  'Filtrerande':'Filtr.', 'Bör-tänkande':'Bör-tänk.',
};

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const [expanded, setExpanded]    = useState(null);
  const isEmpty = moods.length === 0 && thoughts.length === 0;
  const maxTrap = Math.max(...Object.values(trapCounts), 1);
  const avgEmoji = ['','😔','😟','😐','🙂','😄'];

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 24px', position:'relative' }}>
      <Background mood="default" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', animation:'fadeUp .7s both' }}>
        <MeshSphere size={180} speed={0.3} distort={0.35} />
        <h2 style={{ fontSize:26, fontWeight:700, letterSpacing:'-0.03em', color:'#1c1917', marginTop:20, marginBottom:10 }}>Ingenting här än</h2>
        <p style={{ fontSize:14, color:'rgba(28,25,23,0.45)', marginBottom:32, fontWeight:300, maxWidth:220, margin:'0 auto 32px' }}>
          Börja med en tanke eller check-in.
        </p>
        <div style={{ display:'flex', gap:8, justifyContent:'center' }}>
          <button onClick={()=>setPage('home')} style={{ padding:'12px 22px', borderRadius:100, background:'#1c1917', color:'#f2efea', fontSize:13, fontWeight:600, border:'none', boxShadow:'0 4px 16px rgba(0,0,0,0.14)' }}>Analysera</button>
          <button onClick={()=>setPage('checkin')} style={{ padding:'12px 22px', borderRadius:100, background:'rgba(255,255,255,0.6)', border:'1px solid rgba(255,255,255,0.85)', color:'rgba(28,25,23,0.6)', fontSize:13, backdropFilter:'blur(12px)' }}>Check-in</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', paddingBottom:96, position:'relative' }}>
      <Background mood="default" />

      <div style={{ position:'relative', zIndex:1, padding:'28px 24px 0', animation:'fadeUp .7s both' }}>

        {/* Header — editorial, big */}
        <div style={{ marginBottom:28 }}>
          <p style={{ fontSize:11, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.1em', color:'rgba(28,25,23,0.32)', marginBottom:8 }}>Din historik</p>
          <h1 style={{ fontSize:'clamp(34px,8vw,52px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.95, color:'#1c1917' }}>
            {thoughts.length} analyser<br/>
            <span style={{ fontStyle:'italic', fontWeight:300, color:'rgba(28,25,23,0.35)' }}>{streak > 0 ? `${streak} dagars streak` : 'ingen streak än'}</span>
          </h1>
        </div>

        {/* Mood strip — compact visual row */}
        {moods.length > 0 && (
          <div style={{ marginBottom:24 }}>
            <p style={{ fontSize:11, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.08em', color:'rgba(28,25,23,0.32)', marginBottom:10 }}>Humör senaste dagarna</p>
            <div style={{ display:'flex', gap:3, alignItems:'flex-end', height:48 }}>
              {[...moods].reverse().map((m, i) => (
                <div key={i} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2, justifyContent:'flex-end', height:'100%' }}>
                  <div style={{ width:'100%', minHeight:3, background:MOOD_COLOR[m.score], opacity:0.72, borderRadius:'3px 3px 0 0', height:`${(m.score/5)*100}%`, transition:'height .5s' }} title={MOOD_LABEL[m.score]} />
                  <span style={{ fontSize:6, color:'rgba(28,25,23,0.25)', whiteSpace:'nowrap' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Stat pills — inline, airy */}
        <div style={{ display:'flex', gap:8, marginBottom:24, flexWrap:'wrap' }}>
          {[
            { val: avgMood > 0 ? `${avgEmoji[Math.round(avgMood)]} ${avgMood}` : '—', label:'Snitt humör' },
            { val: thoughts.length, label:'Analyser' },
            { val: streak > 0 ? `${streak} dagar` : '—', label:'Streak' },
          ].map(({ val, label }) => (
            <div key={label} style={{ padding:'9px 16px', background:'rgba(255,255,255,0.55)', backdropFilter:'blur(14px)', border:'1px solid rgba(255,255,255,0.8)', borderRadius:100, boxShadow:'0 1px 6px rgba(0,0,0,0.04)' }}>
              <span style={{ fontSize:13, fontWeight:600, color:'#1c1917' }}>{val}</span>
              <span style={{ fontSize:11, color:'rgba(28,25,23,0.38)', marginLeft:5 }}>{label}</span>
            </div>
          ))}
        </div>

        {/* Thin divider */}
        <div style={{ height:1, background:'rgba(28,25,23,0.07)', marginBottom:20 }} />

        {/* Trap frequency — very minimal */}
        {Object.keys(trapCounts).length > 0 && (
          <div style={{ marginBottom:24 }}>
            <p style={{ fontSize:11, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.08em', color:'rgba(28,25,23,0.32)', marginBottom:12 }}>Vanligaste tankefällor</p>
            <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
              {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([label,count]) => (
                <div key={label} style={{ display:'flex', alignItems:'center', gap:10 }}>
                  <span style={{ fontSize:12, color:'rgba(28,25,23,0.55)', flex:1, fontWeight:300 }}>{label}</span>
                  <div style={{ width:80, height:3, background:'rgba(28,25,23,0.07)', borderRadius:2, flexShrink:0 }}>
                    <div style={{ height:'100%', borderRadius:2, background:'rgba(28,25,23,0.28)', width:`${(count/maxTrap)*100}%`, transition:'width .8s cubic-bezier(0.16,1,0.3,1)' }} />
                  </div>
                  <span style={{ fontSize:11, color:'rgba(28,25,23,0.32)', width:14, textAlign:'right', fontWeight:600 }}>{count}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Thought timeline — expandable entries */}
        {thoughts.length > 0 && (
          <>
            <div style={{ height:1, background:'rgba(28,25,23,0.07)', marginBottom:16 }} />
            <p style={{ fontSize:11, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.08em', color:'rgba(28,25,23,0.32)', marginBottom:14 }}>
              Tankelog
            </p>
            <div style={{ display:'flex', flexDirection:'column', gap:2 }}>
              {thoughts.map((th, i) => (
                <div key={th.id}>
                  {/* Entry row — tap to expand */}
                  <button
                    onClick={() => setExpanded(expanded === i ? null : i)}
                    style={{
                      width:'100%', textAlign:'left', padding:'13px 16px',
                      background: expanded === i ? 'rgba(255,255,255,0.62)' : 'rgba(255,255,255,0.38)',
                      backdropFilter:'blur(14px)',
                      border:'1px solid rgba(255,255,255,0.75)',
                      borderRadius: expanded === i ? '16px 16px 0 0' : 16,
                      transition:'all .2s',
                      display:'flex', alignItems:'center', gap:12,
                    }}>
                    {/* Date dot */}
                    <div style={{ flexShrink:0, display:'flex', flexDirection:'column', alignItems:'center', gap:2 }}>
                      <div style={{ width:6, height:6, borderRadius:'50%', background:'rgba(28,25,23,0.2)' }} />
                    </div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:3 }}>
                        <span style={{ fontSize:11, fontWeight:600, color:'rgba(28,25,23,0.55)', textTransform:'uppercase', letterSpacing:'0.06em' }}>
                          {th.trap_icon || '→'} {TRAP_SHORT[th.trap_label] || th.trap_label}
                        </span>
                        <span style={{ fontSize:10, color:'rgba(28,25,23,0.28)' }}>
                          {new Date(th.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                        </span>
                      </div>
                      <p style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontStyle:'italic', margin:0, overflow:'hidden', textOverflow:'ellipsis', whiteSpace: expanded===i ? 'normal' : 'nowrap' }}>
                        "{th.user_text?.slice(0,80)}{th.user_text?.length>80&&expanded!==i?'...':th.user_text?.length>80?'':''}
                      </p>
                    </div>
                    <span style={{ fontSize:12, color:'rgba(28,25,23,0.25)', flexShrink:0, transform: expanded===i?'rotate(180deg)':'none', transition:'transform .25s' }}>↓</span>
                  </button>

                  {/* Expanded content */}
                  {expanded === i && (
                    <div style={{ padding:'12px 16px 14px', background:'rgba(255,255,255,0.55)', backdropFilter:'blur(14px)', border:'1px solid rgba(255,255,255,0.75)', borderTop:'none', borderRadius:'0 0 16px 16px', animation:'fadeUp .3s both' }}>
                      <p style={{ fontSize:11, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.07em', color:'rgba(28,25,23,0.32)', marginBottom:6 }}>Omramning</p>
                      <p style={{ fontSize:13, color:'rgba(28,25,23,0.68)', lineHeight:1.75, fontWeight:300 }}>{th.reframe}</p>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
}
